Analysis: I need to understand what component 11 (benchmark selector) looks like and what values it accepts. Let me explore the components to find the benchmark dropdown with Scandinavian options.
Plan: Look at the components in the config to find the benchmark selector (component 11) and its available values, then try to call the API.
[tool_use bash_command] python3 << 'EOF'
import requests, json

r = requests.get('https://mteb-leaderboard.hf.space/config', timeout=15)
config = r.json()

# Look at components 11, 3, 5, 4, 7, 6, 77, 107, 78
for comp in config['components']:
    comp_id = comp.get('id')
    if comp_id in [11, 3, 5, 4, 6, 7, 77, 78, 107]:
        print(f'\nComponent {comp_id}: type={comp.get("type")}')
        props = comp.get('props', {})
        if 'choices' in props:
            choices = props['choices']
            print(f'  choices ({len(choices)}): {choices[:10]}')
        if 'value' in props:
            val = props['value']
            if isinstance(val, str) or isinstance(val, (int, float, bool)):
                print(f'  value: {val}')
            elif isinstance(val, list) and len(val) < 20:
                print(f'  value: {val}')
            else:
                print(f'  value type: {type(val).__name__}, len: {len(val) if hasattr(val, "__len__") else "N/A"}')
        if 'label' in props:
            print(f'  label: {props["label"]}')
EOF

