from gradio_client import Client
import json

client = Client("mteb/leaderboard")

# Try calling on_benchmark_select to get the Scandinavian benchmark config
try:
    result = client.predict(
        benchmark="MTEB(Scandinavian, v1)",
        api_name="/on_benchmark_select"
    )
    print(type(result))
    if isinstance(result, tuple):
        for i, r in enumerate(result):
            print(f'\nResult {i}: type={type(r).__name__}')
            if isinstance(r, dict):
                print(f'  keys: {list(r.keys())[:10]}')
                for k, v in list(r.items())[:3]:
                    print(f'  {k}: {str(v)[:200]}')
            elif isinstance(r, list):
                print(f'  list of {len(r)}')
                if r: print(f'  first: {str(r[0])[:200]}')
            else:
                print(f'  {str(r)[:300]}')
    else:
        print(str(result)[:2000])
except Exception as e:
    print(f'Error: {e}')
PYEOF

